const dialog=$('#details-dialog');let opener;
function openDetails(key,source){const record=records[key];if(!record)return;opener=source;$('#dialog-kicker').textContent=record.k;$('#dialog-title').textContent=record.title;$('#dialog-copy').textContent=record.copy;const productImage=$('#dialog-product-image');$('#dialog-product-stage').hidden=!record.image;const shineSlot=$('#dialog-shine-slot');shineSlot.replaceChildren();dialog.classList.toggle('gold-dialog',!!record.image);if(record.image){const card=$('[data-prize="'+key+'"] img');productImage.src=card.src;productImage.alt=card.alt;const shine=card.parentElement.querySelector('.gold-shine');if(shine)shineSlot.append(shine.cloneNode(true))}else{productImage.removeAttribute('src');productImage.alt=''};const link=$('#dialog-link');link.href=record.href||'tel:72726565';$('#dialog-link-label').textContent=record.action||'7272 6565 · Лавлах';$('#dialog-messenger-icon').toggleAttribute('hidden',key!=='entries');if(record.href){link.target='_blank';link.rel='noopener'}else{link.removeAttribute('target');link.removeAttribute('rel')}dialog.showModal();document.body.classList.add('modal-open')}
