const reduced=matchMedia('(prefers-reduced-motion: reduce)');
let manuallyPaused=false;const motionButton=$('#motion-toggle');
function syncMotion(){const paused=manuallyPaused||reduced.matches;document.documentElement.classList.toggle('motion-paused',paused);motionButton.setAttribute('aria-pressed',String(paused));motionButton.textContent=paused?'▶':'Ⅱ';const label=paused?'Хөдөлгөөн үргэлжлүүлэх':'Хөдөлгөөн зогсоох';motionButton.setAttribute('aria-label',label);motionButton.title=label;motionButton.hidden=reduced.matches;motionButton.disabled=reduced.matches}
