function updateCountdown(){const now=Date.now();let seconds=Math.max(0,Math.ceil((countdownTarget-now)/1000));$('.launch-clock').style.setProperty('--ring-offset',String(100-(seconds%60)/60*100));const values=[Math.floor(seconds/86400),Math.floor(seconds%86400/3600),Math.floor(seconds%3600/60),seconds%60];['days','hours','minutes','seconds'].forEach((name,i)=>{const el=$('#clock-'+name),next=String(values[i]).padStart(2,'0');if(el.textContent!==next){const old=el.textContent;el.textContent=next;if(old!=='--'&&!reduced.matches&&!manuallyPaused){el.getAnimations().forEach(a=>a.cancel());el.animate([{transform:'translateY(-5px)',opacity:.45},{transform:'translateY(0)',opacity:1}],{duration:260,easing:'ease-out'})}}});if(now>=countdownTarget){$('#draw-results').hidden=false;$('.launch-clock').setAttribute('aria-label','Тохирлын цаг болсон');$('#countdown-title').textContent=now<drawDayEnd?'Тохирлын цаг боллоо!':'Тохирлын мэдээлэл';} }
